INSERT [dbo].[FI_FIELD_DESCR] ([IDCol], [TableName], [Fieldname], [AliasName], [TableAlias], [FieldType]) VALUES (5, N'FOL_TRAN', N'F_POSTCODE', N'Posting code. Mapped to POST_DEF.P_Code', N'Vw_FOL_TRAN', N'VARCHAR (06)')
INSERT [dbo].[FI_FIELD_DESCR] ([IDCol], [TableName], [Fieldname], [AliasName], [TableAlias], [FieldType]) VALUES (6, N'FOL_TRAN', N'F_ADJ_CORR', N'Adjustment flag – left empty if posting has not had an adjustment record added otherwise a - - is put there.', N'Vw_FOL_TRAN', N'VARCHAR (01)')
INSERT [dbo].[FI_FIELD_DESCR] ([IDCol], [TableName], [Fieldname], [AliasName], [TableAlias], [FieldType]) VALUES (7, N'FOL_TRAN', N'F_PID', N'Operator ID who made the posting. - AUTO- if Autoposted.', N'Vw_FOL_TRAN', N'VARCHAR (31)')
