INSERT [dbo].[FI_FIELD_DESCR] ([IDCol], [TableName], [Fieldname], [AliasName], [TableAlias], [FieldType]) VALUES (9, N'FOL_TRAN', N'F_VALUE', N'', N'Vw_FOL_TRAN', N'FLOAT')
