INSERT [dbo].[FI_FIELD_DESCR] ([IDCol], [TableName], [Fieldname], [AliasName], [TableAlias], [FieldType]) VALUES (11, N'FOL_TRAN', N'F_VAT_RATE', N'VAT Rate % applied when this posting was made. Normally 1 through 3, 0 in the case of a Settlement Payment', N'Vw_FOL_TRAN', N'FLOAT')
INSERT [dbo].[FI_FIELD_DESCR] ([IDCol], [TableName], [Fieldname], [AliasName], [TableAlias], [FieldType]) VALUES (12, N'FOL_TRAN', N'F_VAT_AMT', N'Total amount of VAT contained (or added to) this posting.', N'Vw_FOL_TRAN', N'FLOAT')
INSERT [dbo].[FI_FIELD_DESCR] ([IDCol], [TableName], [Fieldname], [AliasName], [TableAlias], [FieldType]) VALUES (13, N'FOL_TRAN', N'F_ONINV', N'If this has been invoiced then the Invoice number goes here.', N'Vw_FOL_TRAN', N'VARCHAR (07)')
INSERT [dbo].[FI_FIELD_DESCR] ([IDCol], [TableName], [Fieldname], [AliasName], [TableAlias], [FieldType]) VALUES (14, N'FOL_TRAN', N'F_INVDATE', N'If this has been Invoiced AND succesfully printed then the Invoice date goes here. If the Invoice has been raised but the operator has not confirmed everything printed OK then the Date is left NULL', N'Vw_FOL_TRAN', N'DATETIME')
